-- Deterministic development-only mock data for the 21 existing systems (10-20 evaluators/system).
-- Re-running this file replaces only rows marked with mock-* / mock_* markers.
-- Password hashes and salts are random independent values; mock users have no usable credentials.
PRAGMA foreign_keys = ON;
BEGIN IMMEDIATE;
DELETE FROM assessment_answers WHERE evaluation_id IN (SELECT id FROM evaluations WHERE id GLOB 'mock-eval-*');
DELETE FROM satisfactions WHERE evaluation_id GLOB 'mock-eval-*';
DELETE FROM evaluations WHERE id GLOB 'mock-eval-*';
DELETE FROM quantitative_records WHERE id GLOB 'mock-quant-*';
DELETE FROM auth_sessions WHERE user_id IN (SELECT id FROM users WHERE username GLOB 'mock_*');
DELETE FROM users WHERE username GLOB 'mock_*';

-- Mock accounts are synthetic; no password is supplied or known.

CREATE TEMP TABLE mock_eval_seed (id TEXT PRIMARY KEY,system_id TEXT NOT NULL,user_id TEXT NOT NULL,submitted_at TEXT NOT NULL,before_answers TEXT NOT NULL,after_answers TEXT NOT NULL,before_average REAL,after_average REAL,satisfaction_answers TEXT NOT NULL,satisfaction_average REAL,user_role TEXT NOT NULL,feedback TEXT NOT NULL);


CREATE TEMP TABLE mock_quant_seed (id TEXT PRIMARY KEY,system_id TEXT NOT NULL,user_id TEXT NOT NULL,submitted_at TEXT NOT NULL,values_json TEXT NOT NULL);

DROP TABLE mock_eval_seed;
DROP TABLE mock_quant_seed;
COMMIT;
